query:
create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  full_name text,
  avatar_url text,
  cloudinary_public_id text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.schools (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(name) between 2 and 160),
  slug text not null unique check (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'),
  abbreviation text,
  email text,
  phone text,
  whatsapp text,
  address text,
  city text,
  country text not null default 'Sénégal',
  website text,
  establishment_type text,
  logo_url text,
  logo_cloudinary_public_id text,
  created_by uuid not null references auth.users(id) on delete restrict,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.school_memberships (
  school_id uuid not null references public.schools(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  role text not null check (role in ('owner','director','administrator','secretary','accountant','teacher','supervisor','parent','student')),
  created_at timestamptz not null default now(),
  primary key (school_id, user_id)
);

create table if not exists public.academic_years (
  id uuid primary key default gen_random_uuid(),
  school_id uuid not null references public.schools(id) on delete cascade,
  label text not null,
  starts_on date not null,
  ends_on date not null,
  is_current boolean not null default false,
  created_at timestamptz not null default now(),
  unique (school_id, label),
  check (ends_on > starts_on)
);

create unique index if not exists academic_years_one_current_per_school on public.academic_years (school_id) where is_current;

create table if not exists public.classes (
  id uuid primary key default gen_random_uuid(),
  school_id uuid not null references public.schools(id) on delete cascade,
  academic_year_id uuid not null references public.academic_years(id) on delete cascade,
  level_name text not null,
  name text not null,
  capacity integer check (capacity is null or capacity > 0),
  principal_teacher_id uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  unique (school_id, academic_year_id, name)
);

create table if not exists public.students (
  id uuid primary key default gen_random_uuid(),
  school_id uuid not null references public.schools(id) on delete cascade,
  student_number text not null unique,
  first_name text not null,
  last_name text not null,
  birth_date date,
  birth_place text,
  gender text check (gender in ('female','male','other','undisclosed')),
  photo_url text,
  photo_cloudinary_public_id text,
  address text,
  phone text,
  email text,
  guardian_name text,
  guardian_phone text,
  status text not null default 'active' check (status in ('active','inactive','graduated','withdrawn')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.student_enrollments (
  id uuid primary key default gen_random_uuid(),
  school_id uuid not null references public.schools(id) on delete cascade,
  student_id uuid not null references public.students(id) on delete cascade,
  academic_year_id uuid not null references public.academic_years(id) on delete cascade,
  class_id uuid references public.classes(id) on delete set null,
  enrolled_on date not null default current_date,
  status text not null default 'enrolled' check (status in ('enrolled','transferred','withdrawn','completed')),
  created_at timestamptz not null default now(),
  unique (student_id, academic_year_id)
);

create table if not exists public.media_assets (
  id uuid primary key default gen_random_uuid(),
  school_id uuid not null references public.schools(id) on delete cascade,
  owner_id uuid references auth.users(id) on delete set null,
  kind text not null check (kind in ('school_logo','user_avatar','student_photo','document','other')),
  cloudinary_public_id text not null unique,
  delivery_url text not null,
  mime_type text,
  bytes bigint,
  created_at timestamptz not null default now()
);

create index if not exists school_memberships_user_idx on public.school_memberships (user_id);
create index if not exists classes_school_year_idx on public.classes (school_id, academic_year_id);
create index if not exists students_school_idx on public.students (school_id);
create index if not exists student_enrollments_school_year_idx on public.student_enrollments (school_id, academic_year_id);
create index if not exists media_assets_school_idx on public.media_assets (school_id);

create or replace function public.set_updated_at() returns trigger language plpgsql security invoker set search_path = public as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists profiles_set_updated_at on public.profiles;
create trigger profiles_set_updated_at before update on public.profiles for each row execute function public.set_updated_at();
drop trigger if exists schools_set_updated_at on public.schools;
create trigger schools_set_updated_at before update on public.schools for each row execute function public.set_updated_at();
drop trigger if exists students_set_updated_at on public.students;
create trigger students_set_updated_at before update on public.students for each row execute function public.set_updated_at();

create or replace function public.is_school_member(target_school_id uuid) returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.school_memberships where school_id = target_school_id and user_id = auth.uid());
$$;

create or replace function public.create_school_with_owner(p_name text, p_slug text, p_city text default null, p_country text default 'Sénégal') returns jsonb language plpgsql security definer set search_path = public, auth as $$
declare
  new_school public.schools;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;
  insert into public.profiles (id, full_name)
  values (auth.uid(), coalesce((select raw_user_meta_data ->> 'full_name' from auth.users where id = auth.uid()), (select email from auth.users where id = auth.uid())))
  on conflict (id) do nothing;
  insert into public.schools (name, slug, city, country, created_by)
  values (trim(p_name), lower(trim(p_slug)), nullif(trim(p_city), ''), coalesce(nullif(trim(p_country), ''), 'Sénégal'), auth.uid())
  returning * into new_school;
  insert into public.school_memberships (school_id, user_id, role)
  values (new_school.id, auth.uid(), 'owner');
  return jsonb_build_object('id', new_school.id, 'name', new_school.name, 'slug', new_school.slug, 'role', 'owner');
end;
$$;

revoke all on function public.create_school_with_owner(text, text, text, text) from public;
grant execute on function public.create_school_with_owner(text, text, text, text) to authenticated;

alter table public.profiles enable row level security;
alter table public.schools enable row level security;
alter table public.school_memberships enable row level security;
alter table public.academic_years enable row level security;
alter table public.classes enable row level security;
alter table public.students enable row level security;
alter table public.student_enrollments enable row level security;
alter table public.media_assets enable row level security;

create policy profiles_select_own on public.profiles for select to authenticated using (id = auth.uid());
create policy profiles_update_own on public.profiles for update to authenticated using (id = auth.uid()) with check (id = auth.uid());
create policy schools_select_member on public.schools for select to authenticated using (public.is_school_member(id));
create policy schools_insert_owner on public.schools for insert to authenticated with check (created_by = auth.uid());
create policy schools_update_owner on public.schools for update to authenticated using (created_by = auth.uid()) with check (created_by = auth.uid());
create policy memberships_select_member on public.school_memberships for select to authenticated using (public.is_school_member(school_id));
create policy academic_years_member_access on public.academic_years for all to authenticated using (public.is_school_member(school_id)) with check (public.is_school_member(school_id));
create policy classes_member_access on public.classes for all to authenticated using (public.is_school_member(school_id)) with check (public.is_school_member(school_id));
create policy students_member_access on public.students for all to authenticated using (public.is_school_member(school_id)) with check (public.is_school_member(school_id));
create policy enrollments_member_access on public.student_enrollments for all to authenticated using (public.is_school_member(school_id)) with check (public.is_school_member(school_id));
create policy media_assets_member_access on public.media_assets for all to authenticated using (public.is_school_member(school_id)) with check (public.is_school_member(school_id));
